public enum ChartError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidLane(object: UInt32
    )
    case InvalidHold(object: UInt32
    )
    case OutsideDuration(object: UInt32
    )
    case NotSorted(object: UInt32
    )
    case SameLaneOverlap(object: UInt32
    )
    case InvalidTime(object: UInt32
    )
    case BeforeCoverage(object: UInt32
    )
    case HoldEndWithoutStart(lane: UInt32
    )
    case UnclosedHold(object: UInt32
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension ChartError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeChartError: FfiConverterRustBuffer {
    typealias SwiftType = ChartError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ChartError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidLane(
            object: try FfiConverterUInt32.read(from: &buf)
            )
        case 2: return .InvalidHold(
            object: try FfiConverterUInt32.read(from: &buf)
            )
        case 3: return .OutsideDuration(
            object: try FfiConverterUInt32.read(from: &buf)
            )
        case 4: return .NotSorted(
            object: try FfiConverterUInt32.read(from: &buf)
            )
        case 5: return .SameLaneOverlap(
            object: try FfiConverterUInt32.read(from: &buf)
            )
        case 6: return .InvalidTime(
            object: try FfiConverterUInt32.read(from: &buf)
            )
        case 7: return .BeforeCoverage(
            object: try FfiConverterUInt32.read(from: &buf)
            )
        case 8: return .HoldEndWithoutStart(
            lane: try FfiConverterUInt32.read(from: &buf)
            )
        case 9: return .UnclosedHold(
            object: try FfiConverterUInt32.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ChartError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidLane(object):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(object, into: &buf)
            
        
        case let .InvalidHold(object):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(object, into: &buf)
            
        
        case let .OutsideDuration(object):
            writeInt(&buf, Int32(3))
            FfiConverterUInt32.write(object, into: &buf)
            
        
        case let .NotSorted(object):
            writeInt(&buf, Int32(4))
            FfiConverterUInt32.write(object, into: &buf)
            
        
        case let .SameLaneOverlap(object):
            writeInt(&buf, Int32(5))
            FfiConverterUInt32.write(object, into: &buf)
            
        
        case let .InvalidTime(object):
            writeInt(&buf, Int32(6))
            FfiConverterUInt32.write(object, into: &buf)
            
        
        case let .BeforeCoverage(object):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(object, into: &buf)
            
        
        case let .HoldEndWithoutStart(lane):
            writeInt(&buf, Int32(8))
            FfiConverterUInt32.write(lane, into: &buf)
            
        
        case let .UnclosedHold(object):
            writeInt(&buf, Int32(9))
            FfiConverterUInt32.write(object, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeChartError_lift(_ buf: RustBuffer) throws -> ChartError {
    return try FfiConverterTypeChartError.lift(buf)
}

